# Page content for marcellspaper.com v3 (Pioneer-direction restyle, 2026-09-23). Edit here, run tools/build_site.py, push.

PAGES = {
    'index': {"title": 'Marcells Paper & Metal | Recovered paper and metal programs, nationwide', "desc": 'Chicago-based, family-owned since 1979. Mill-direct pricing, equipment financed within your program, and a live portal showing every load and statement. Programs nationwide, domestic and export mills.', "body": '<div class="hero-p"><div class="wrap two">\n  <div class="hero-txt">\n    <div class="pre">Family-owned in Chicago since 1979</div>\n    <h1>Recovered paper and metal programs, <span>run properly.</span></h1>\n    <p class="lead">Mill-direct pricing, the right equipment, and a live portal showing every load and every statement — for one plant or a national footprint. Paper, metal, plastics and pallets on one pickup.</p>\n    <div class="ul-links"><a href="services.html">Our services</a><a href="portal.html">The customer portal</a><a href="contact.html">Request a quote</a></div>\n  </div>\n  <div class="hero-img"><img src="assets/mpm2-bales.jpg" alt="Bales of recovered paper at the MPM plant"></div>\n</div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div>\n\n<section><div class="wrap">\n  <div class="intro">\n    <h2>Our recycling services</h2>\n    <p>MPM builds recovered-material programs around how your plant actually runs. Our services include:</p>\n    <ul class="dash">\n      <li>Plant processing, grading and mill-direct sales of recovered paper</li>\n      <li>Metal, plastics and wooden pallets handled as part of the same program</li>\n      <li>Containers, spotted trailers and scheduled or same-day pickup</li>\n      <li>Confidential document destruction</li>\n      <li>Equipment financing at the right volume and deal structure</li>\n      <li>Online reporting and 24/7 access to your loads, statements and impact</li>\n    </ul>\n    <p><a class="ul-link" href="services.html">See all services</a></p>\n  </div>\n</div></section>\n\n<div class="band-g"><div class="wrap">\n  <div class="proof">\n    <div><b>Since 1979</b><span>family-owned, same phone number, same name on the door</span></div>\n    <div><b>National</b><span>programs in every state, shipping to domestic and export mills</span></div>\n    <div><b>Every load</b><span>visible in your portal — scheduled, shipped, paid — with net weight and value</span></div>\n    <div><b>6 days</b><span>a week, Sunday pickups on request, special pickups dispatched within 24 hours</span></div>\n  </div>\n</div></div>\n\n<section><div class="wrap two">\n  <div>\n    <h2>What we buy, process and sell</h2>\n    <p>Our primary focus is recovered paper in all grades — OCC, DLK, sorted and mixed ledger, news blanks and publication blanks, book stock, hard white and other pulp substitutes — bought mill-direct and baled to mill specification at our Chicago plant.</p>\n    <p>While most people know us for paper, MPM also handles aluminum printing plates and mixed metals, industrial scrap plastics, and — through Marcells Pallet Inc — wooden pallets, so one program covers everything leaving your dock.</p>\n    <div class="ul-links"><a href="paper.html">Paper</a><a href="metal.html">Metal</a><a href="plastics.html">Plastics</a><a href="pallets.html">Pallets</a></div>\n  </div>\n  <div>\n    <h2>Get ready, get set, recycle</h2>\n    <p>Not sure what your material is worth, or how much of it is going out loose? We\'ll come to your site, look at what you ship and how, and show you what a program would look like — no charge, no obligation.</p>\n    <div class="ul-links"><a href="contact.html">Request an on-site assessment</a><a href="contact.html">Request a quote</a></div>\n  </div>\n</div></section>\n\n<div class="band-l"><div class="wrap two">\n  <div>\n    <h2>Your program, visible</h2>\n    <p>Every customer gets a login. Current pricing by grade, every load with weights and values, monthly statements per site, payment status and recycling impact — updated as loads ship, not assembled when you ask.</p>\n    <div class="ul-links"><a href="portal.html">See the portal</a><a href="https://portals.cietrade.com/MarcellsPaperPortal/login.aspx" target="_blank" rel="noopener">Client Login</a></div>\n  </div>\n  <div>\n    <h2>How it all started</h2>\n    <p>A college student, a room full of used punch cards, a $1,000 loan from his grandmother, and a dress shop on Devon Avenue that answered the phone "Marcells." Still family-owned. Still answering the phone.</p>\n    <div class="ul-links"><a href="about.html">Read the story</a></div>\n  </div>\n</div></div>\n'},
    'services': {"title": 'Recycling services | Marcells Paper & Metal', "desc": 'Plant processing, mill-direct sales, document destruction, waste stream assessment, equipment financing, online reporting, nationwide programs, containers and pickup, pallets.', "body": '<div class="head-g"><div class="wrap"><div class="pre">Services</div><h1>Everything a recovered-paper program needs, from one company.</h1>\n<p class="lead">MPM works with printers, converters, manufacturers and distribution centers — one plant or forty, local or national. Processing, mill-direct sales, equipment, containers, document destruction and live reporting, all under one program.</p></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div>\n\n<section><div class="wrap">\n  <div class="grid3">\n    <div><h3 class="lab">Plant Processing</h3><p>Our Chicago plant grades, weighs and bales recovered paper to mill specification on a computerized scale system, with adjacent rail service to move material efficiently.</p></div><div><h3 class="lab">Mill Direct</h3><p>We sell straight to paper mills across the country and overseas, so your price comes from the mill — not from a broker sitting between you and it.</p></div><div><h3 class="lab">Document Destruction</h3><p>Sensitive files and materials are collected discreetly and destroyed at an isolated site inside our plant, under 24-hour video surveillance with remote viewing.</p></div><div><h3 class="lab">Waste Stream Assessment</h3><p>We walk your floor and look at what\'s going out — grades, weights, trucks, what\'s loose — and show you where you\'re paying to move air and how to stop.</p></div><div><h3 class="lab">Equipment Financing</h3><p>For sites with the right volume and deal structure, we finance balers, compactors and conveying equipment within the program.</p></div><div><h3 class="lab">Online Reporting</h3><p>Secure, real-time access to your pricing, loads, statements, payments and recycling impact through the customer portal — updated as loads ship.</p></div><div><h3 class="lab">Nationwide Programs</h3><p>One program across every site, coast to coast, coordinated from one Chicago operations desk — same grades, same reporting, same people.</p></div><div><h3 class="lab">Containers &amp; Pickup</h3><p>Gaylords, plastic tubs, collapsible containers, bins and spotted trailers, with scheduled pickups and same-day service on requests before 10:00 am.</p></div><div><h3 class="lab">Pallets</h3><p>Marcells Pallet Inc builds, repairs, recycles and sells wooden pallets for the same customers — one pickup, one invoice.</p></div>\n  </div>\n</div></section>\n\n<div class="band-l"><div class="wrap">\n  <h2>What a program looks like</h2>\n  <div class="steps-p">\n    <div><b>01</b><h3>We look at what you\'re actually shipping.</h3><p>Load weights, grades, how many trucks a month, what\'s going out loose. Most sites are paying to move air.</p></div>\n    <div><b>02</b><h3>We fix the material before we fix the price.</h3><p>Baled beats loose by a wide margin — heavier loads, fewer trucks, better grade. If equipment is what\'s standing in the way, that\'s our problem to solve.</p></div>\n    <div><b>03</b><h3>We get the equipment in.</h3><p>Balers, conveyors, cart tippers, roll cutters — sized to your tonnage. At the right volume and deal structure we finance it within the program.</p></div>\n    <div><b>04</b><h3>One program across every site.</h3><p>Same grades, same reporting, same contacts. We coordinate spotted trailers, owner-operators and third-party carriers between sites and mills.</p></div>\n    <div><b>05</b><h3>You see everything.</h3><p>Monthly statements per site, and a portal that updates as loads ship — pricing, loads, payments, impact.</p></div>\n  </div>\n</div></div>\n\n<section><div class="wrap two">\n  <div><h2>Programs built around your plant</h2><p>Every site is different: different grades, different volumes, different dock. We build the program to fit — the containers, the pickup schedule, the equipment if it\'s warranted — and we don\'t publish customer names or use them in our marketing.</p></div>\n  <div><h2>Service you can actually reach</h2><p>You always talk to a person. Same-day service on requests before 10:00 am and never later than the next morning; six days a week, Sunday on request; special pickups dispatched within 24 hours. Prompt payment, and a statement you can audit.</p>\n  <div class="ul-links"><a href="contact.html">Have us look at your loads</a><a href="tel:+17732651200">(773) 265-1200</a></div></div>\n</div></section>\n'},
    'portal': {"title": 'Customer portal | Marcells Paper & Metal', "desc": 'Every MPM customer gets a login: pricing by grade, every load with weights and values, monthly statements, payments and recycling impact — updated as loads ship.', "body": '<div class="head-g"><div class="wrap"><div class="pre">The portal</div><h1>Your program, visible.</h1>\n<p class="lead">Every customer gets a login. Pricing, loads, statements, payments and impact — updated as loads ship, not assembled when you ask.</p>\n<div class="ul-links"><a href="https://portals.cietrade.com/MarcellsPaperPortal/login.aspx" target="_blank" rel="noopener">Client Login</a><a href="contact.html">Ask for a walkthrough</a></div></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div>\n<section><div class="wrap">\n  <div class="grid3">\n    <div><h3 class="lab">Pricing</h3><p>Your current price on every grade, in one place, with the basis it rides on. No calling to ask what you\'re getting.</p></div>\n    <div><h3 class="lab">Loads</h3><p>Every load with date, ticket number, grade, net weight and value — from scheduled through shipped to paid — filtered by site, month or grade.</p></div>\n    <div><h3 class="lab">Statements</h3><p>A monthly statement per site, downloadable as a PDF, with a running balance that ties to your payments.</p></div>\n    <div><h3 class="lab">Payments</h3><p>What\'s been paid and what\'s coming, with dates and the loads each payment covers. No chasing accounts payable.</p></div>\n    <div><h3 class="lab">Environmental Impact</h3><p>Tons recycled, trees, water, energy and CO₂e by site and month — exportable for your own sustainability reporting.</p></div>\n    <div><h3 class="lab">Documents</h3><p>The Marcells scale ticket and bill of lading for every load, available to open or download the moment it\'s weighed.</p></div>\n  </div>\n</div></section>\n<div class="band-l"><div class="wrap two">\n  <div><h2>Updated as loads ship</h2><p>Every load posts to your login when it crosses our scale. Status moves from scheduled to shipped to paid without a phone call.</p></div>\n  <div><h2>Built for multi-site programs</h2><p>One login can cover every plant in your network, with the same grades, the same reporting and the same people behind it — or a separate login per site if that\'s how you run.</p>\n  <div class="ul-links"><a href="contact.html">See it on a call</a></div></div>\n</div></div>'},
    'equipment': {"title": 'Equipment | Marcells Paper & Metal', "desc": 'Balers, conveyors, roll cutters, cart tippers, compactors and containers sized to your tonnage; equipment financing at the right volume and deal structure.', "body": '<div class="head-g"><div class="wrap"><div class="pre">Equipment</div><h1>The right equipment, sized to your tonnage.</h1>\n<p class="lead">Loose material on trucks is what costs you money; the equipment is how that stops. We size it to what your facility actually produces and support it for the life of the program.</p></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div>\n<section><div class="wrap">\n  <div class="grid3">\n    <div><h3 class="lab">Balers</h3><p>Vertical and horizontal, matched to your monthly tonnage.</p></div>\n    <div><h3 class="lab">Conveyors</h3><p>Feed from the floor or the line straight into the baler.</p></div>\n    <div><h3 class="lab">Roll Cutters</h3><p>For converters and printers running rolls and trim.</p></div>\n    <div><h3 class="lab">Cart Tippers</h3><p>Empty tubs and carts into the baler without lifting.</p></div>\n    <div><h3 class="lab">Compactors</h3><p>For sites where volume calls for it.</p></div>\n    <div><h3 class="lab">Containers</h3><p>Gaylord boxes, plastic tubs, collapsible containers, bin receptacles and spotted trailers dropped at your facility.</p></div>\n  </div>\n</div></section>\n<div class="band-l"><div class="wrap two">\n  <div><h2>Financing</h2><p>For sites with the right volume and deal structure, we finance balers, compactors and conveying equipment within the program. Terms are discussed site by site and never published.</p></div>\n  <div><h2>How sizing works</h2><p>A site analysis based on the tonnage your facility produces. Equipment matched to that tonnage — not the biggest machine we can place — with training and ongoing support included.</p>\n  <div class="ul-links"><a href="contact.html">Ask about an equipment program</a></div></div>\n</div></div>\n'},
    'coverage': {"title": 'Coverage | Marcells Paper & Metal', "desc": 'Headquartered in Chicago, programs in every state, material shipped to domestic and export mills.', "body": '<section><div class="wrap split">\n  <div><div class="pre">Coverage</div><h1>Where we run: everywhere.</h1><p class="lead" style="margin-top:18px">Headquartered in Chicago at 4221 W Ferdinand. Programs across the whole country, coordinated from one operations desk — and material shipped wherever it earns the most, including export mills overseas.</p>\n  <div class="covs">\n    <div><b>All 48 contiguous states</b><span>Pickups, spotted trailers and program sites coast to coast</span></div>\n    <div><b>Domestic mills</b><span>Direct relationships, not a broker between you and the buyer</span></div>\n    <div><b>Export</b><span>Containerized loads to overseas mills when that\'s the best home for your grade</span></div>\n    <div><b>One desk</b><span>Same contacts, same reporting, whether the site is in Chicago or on the coast</span></div>\n  </div>\n  <p style="margin-top:26px"><a class="btn" href="contact.html">Ask about your region</a> &nbsp; <span class="muted" style="font-size:14px">or call (773) 265-1200</span></p></div>\n  <div>\n    <div class="map">\n      <i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="on">ME</i>\n      <i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="on">VT</i><i class="on">NH</i>\n      <i class="on">WA</i><i class="on">ID</i><i class="on">MT</i><i class="on">ND</i><i class="on">MN</i><i class="on">WI</i><i class="on">MI</i><i class="x"></i><i class="on">NY</i><i class="on">MA</i><i class="on">RI</i>\n      <i class="on">OR</i><i class="on">NV</i><i class="on">WY</i><i class="on">SD</i><i class="on">IA</i><i class="hq">IL</i><i class="on">IN</i><i class="on">OH</i><i class="on">PA</i><i class="on">NJ</i><i class="on">CT</i>\n      <i class="on">CA</i><i class="on">UT</i><i class="on">CO</i><i class="on">NE</i><i class="on">MO</i><i class="on">KY</i><i class="on">WV</i><i class="on">VA</i><i class="on">MD</i><i class="on">DE</i><i class="x"></i>\n      <i class="x"></i><i class="on">AZ</i><i class="on">NM</i><i class="on">KS</i><i class="on">AR</i><i class="on">TN</i><i class="on">NC</i><i class="on">SC</i><i class="x"></i><i class="x"></i><i class="x"></i>\n      <i class="x"></i><i class="x"></i><i class="on">TX</i><i class="on">OK</i><i class="on">LA</i><i class="on">MS</i><i class="on">AL</i><i class="on">GA</i><i class="x"></i><i class="x"></i><i class="x"></i>\n      <i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="x"></i><i class="on">FL</i><i class="x"></i><i class="x"></i><i class="x"></i>\n    </div>\n    <div class="exp"><span class="arr">←</span><b>Export</b> Pacific &amp; Atlantic ports → overseas mills <span class="arr">→</span></div>\n    <div class="legend"><span><i style="background:var(--green)"></i>Chicago headquarters</span><span><i style="background:var(--moss)"></i>Program coverage</span></div>\n  </div>\n</div></section>'},
    'about': {"title": 'About | Marcells Paper & Metal', "desc": 'How Scott Lowell turned a trunk of computer punch cards and a $1,000 loan into Marcells Paper & Metal, family-owned since 1979.', "body": '<div class="head-g"><div class="wrap"><div class="pre">About</div><h1>It started with punch cards.</h1></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div>\n<section><div class="wrap"><img class="one-photo" src="assets/mpm2-aisle.jpg" alt="Aisle of finished bales in the MPM warehouse"><div class="story">\n  <p class="drop">Back in the mid to late 70’s, Scott Lowell was your average college student. One of the classes he was taking at the time was Statistics 101. On his way to this particular class, he would pass a room designated for computers only. In those days, the computer industry was just entering its humble beginnings and in order to communicate to computers, one would feed them punch-tab cards to deliver information. This process has since been modernized to what we now refer to as hard-drives on present day computers.</p>\n  <p>Scott noticed that the used key punch cards were being saved and placed back into the original boxes they came in. He got to talking with someone in the room who explained that a service comes in, buys the punch cards back and takes them away. He further learned that paper mills use the old key punch cards by recycling them into other paper products. He also found out that there were companies in the Chicago area that were also interested in buying them back. Scott discovered the name of such a company, called them up and asked them how much they were paying for scrap computer cards.</p>\n  <p>Scott soon realized that this could be a very good business prospect. He noticed that every Sunday when he opened up the job section of the paper, he would see between 300 and 400 want ads seeking computer analysts. Who better to have used computer cards than the companies searching for employees for their computers? Scott wanted to capitalize on the opportunity, but first he needed to do four things: develop a name for his company, open a checking account, get a truck to pick up the scrap computer cards, and find someone to sell them to.</p>\n  <p>Perhaps Scott’s biggest business feat to this day was obtaining the financing needed to purchase his first step van for pick-ups. Scott persuaded his grandmother to loan him $1,000 – which he paid back at $50 a month. At that time, Scott’s mother had a small dress shop located on Devon Avenue in Chicago. It was called “Marcells Custom Tailoring”. Scott explains that his mother always answered the phone the same way, “Marcells”. Marcells was the only word she ever said. Not “Marcells Custom Tailoring”, just “Marcells”. His mom said that she could take all of his calls too — and so the company got its name.</p>\n  <p>On off school days, holidays and such, Scott’s 12-year younger brother Jeff got involved, helping him out on the truck. Scott’s mother continued to answer his phone calls at her dress shop. Scott had business cards made up with the address and phone number of the dress shop. So when his mother answered the phones by saying “Marcells”, whether the caller was a customer of the dress shop or Scott’s paper recycling business in Chicago, IL, they had come to the right place!</p>\n</div>\n<div class="bridge"><h3>From one step van to nationwide programs.</h3><p>The business that started in 1979 with a borrowed $1,000 now runs recovered paper and metal programs across the country, ships to domestic and export mills, and gives every customer a live portal into their loads, statements and impact. Still family-owned. Still answering the phone.</p></div>\n</div></section>'},
    'paper': {"title": 'Paper recycling | Marcells Paper & Metal', "desc": 'All grades of recovered paper — OCC, DLK, ledger, news, high grades and pulp substitutes — bought mill-direct with containers and pickup from MPM.', "body": '<div class="head-g"><div class="wrap"><div class="pre">Materials</div><h1>Paper</h1></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div><section><div class="wrap"><div class="prose">\n<p>MPM buys recovered paper from printers, converters, manufacturers and distribution centers — a broad spectrum of grades from newspaper and corrugated to high grades and pulp substitutes. Our direct relationships with domestic and export mills let us work on your behalf and get the most out of every load.</p>\n<h2>Grades we buy</h2>\n<ul class="dash"><li>Printers mix, sorted and mixed white ledger, colored ledger and envelope cuttings</li><li>Coated and uncoated book stock, news blanks and publication blanks</li><li>Old corrugated containers (OCC), double-lined kraft (DLK) and boxboard</li><li>Old newspaper, magazines and groundwood grades</li><li>Hard white, soft white and other pulp substitutes</li><li>Old inventory of paper — cut sheets and rolls</li></ul>\n<h2>What happens to your paper</h2>\n<p>Every load is weighed at our Chicago facility on a computerized scale system, graded, sorted to remove contaminants, and compacted into mill-specification bales. Our facility has immediate, adjacent rail service, so material moves to mills efficiently. Weights and values post to your portal login as loads cross the scale.</p>\n<h2>Containers and pickup</h2>\n<p>We supply what your site needs — gaylord boxes, plastic tubs, collapsible containers, bin receptacles or a spotted trailer — and schedule pickups around your production. Same-day service on requests before 10:00 am, six days a week, Sunday on request.</p>\n<p>Our sister company, <a href="pallets.html">Marcells Pallet Inc</a>, builds, repairs, recycles and sells pallets for the same customers — one pickup, one invoice, paper and pallets together.</p>\n<p><strong>Call <a href="tel:+17732651200">(773) 265-1200</a> or <a href="contact.html">tell us what you\'re shipping</a>.</strong></p>\n</div></div></section>'},
    'metal': {"title": 'Metal recycling | Marcells Paper & Metal', "desc": 'Aluminum printing plates, mixed metals and bulky items collected and recycled by MPM with containers dropped at your facility.', "body": '<div class="head-g"><div class="wrap"><div class="pre">Materials</div><h1>Metal</h1></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div><section><div class="wrap"><div class="prose">\n<p>MPM isn\'t only paper. We collect and recycle metal waste from printers and manufacturers — aluminum printing plates above all, plus mixed metals and bulky items — with the equipment to strip, load and haul.</p>\n<h2>Why aluminum plates are worth recycling</h2>\n<p>Aluminum keeps its physical properties through recycling, so recycled and virgin aluminum are effectively the same material. Recycling plates reduces reliance on bauxite ore and uses a fraction of the energy of primary production — and it pays.</p>\n<h2>How it works</h2>\n<p>We drop containers of the right size at your facility, you fill them with plates and other metal (and paper), and we collect on a schedule that fits your production. Every load is weighed on our computerized scale and posted to your portal.</p>\n<h2>Construction and industrial metal</h2>\n<p>Any project produces metal waste that shouldn\'t go to a landfill and has to be handled correctly. We take care of collection and recycling so the material ends up where it should, with the paperwork to show it.</p>\n<p><strong>Call <a href="tel:+17732651200">(773) 265-1200</a> or <a href="contact.html">send us a message</a>.</strong></p>\n</div></div></section>'},
    'plastics': {"title": 'Plastics recycling | Marcells Paper & Metal', "desc": 'Industrial scrap plastics — film, strapping, totes and production scrap — collected and recycled by MPM on the same program as your paper and metal.', "body": '<div class="head-g"><div class="wrap"><div class="pre">Materials</div><h1>Plastics</h1></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div><section><div class="wrap"><div class="prose">\n<p>Alongside paper and metal, MPM buys industrial scrap plastics from the same plants — so one program and one pickup cover everything leaving your dock.</p>\n<h2>What we take</h2>\n<ul class="dash"><li>Stretch film and shrink wrap</li><li>Plastic strapping</li><li>Totes, drums, crates and rigid containers</li><li>Production scrap and off-spec material</li></ul>\n<h2>How it works</h2>\n<p>Tell us what the material is and roughly how much you generate. We’ll set up the right container or baling approach, pick it up on your schedule, weigh it on our computerized scale and post it to your portal like any other load.</p>\n<p><strong>Not sure if we take it? Call <a href="tel:+17732651200">(773) 265-1200</a> — if it’s plastic and it’s industrial, we’ll tell you straight.</strong></p>\n</div></div></section>'},
    'pallets': {"title": 'Pallets | Marcells Pallet Inc', "desc": 'Marcells Pallet Inc builds, repairs, recycles and sells pallets — one pickup and one invoice alongside your paper, metal and plastics.', "body": '<div class="head-g"><div class="wrap"><div class="pre">Marcells Pallet Inc</div><h1>Pallets</h1></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div>\n<section><div class="wrap"><div class="prose">\n<p>Marcells Pallet Inc, our sister company, builds, repairs, recycles and sells wooden pallets for the same customers MPM serves for paper, metal and plastics. One pickup, one invoice, everything together.</p>\n<h2>What we do</h2>\n<ul class="dash"><li>Buy back and recycle your used and broken pallets</li><li>Repair and return pallets to service</li><li>Build new pallets to your spec</li><li>Sell new and recycled wooden pallets by the truckload</li></ul>\n<h2>Why it works with a paper program</h2>\n<p>Pallets leave your building on the same trucks as your paper and metal. Putting them on the same program means fewer vendors, fewer trucks and one statement to reconcile.</p>\n<p><strong>Need pallets, or need them gone? Call <a href="tel:+17732651200">(773) 265-1200</a>.</strong></p>\n</div></div></section>'},
    'secure-destruction': {"title": 'Secure document destruction | Marcells Paper & Metal', "desc": 'Discreet collection and destruction of sensitive documents at an isolated site inside the MPM facility under 24-hour video surveillance.', "body": '<div class="head-g"><div class="wrap"><div class="pre">Materials</div><h1>Document destruction</h1></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div><section><div class="wrap"><div class="prose">\n<p>The secure destruction of sensitive documents and files is serious business, which is why MPM added a dedicated, isolated site inside our facility for exactly that purpose.</p>\n<h2>How it works</h2>\n<ul class="dash"><li>Discreet collection of documents and files from your site, on a schedule or on request</li><li>Destruction at an isolated area of our facility used solely for this purpose</li><li>24-hour video surveillance with remote viewing access</li><li>Destroyed material is baled and recycled as paper — nothing goes to landfill</li></ul>\n<p><strong>Call <a href="tel:+17732651200">(773) 265-1200</a> to set up secure destruction for your office or plant.</strong></p>\n</div></div></section>'},
    'faq': {"title": 'FAQ | Marcells Paper & Metal', "desc": 'Answers about coverage, pickups, containers, materials, pricing and the customer portal.', "body": '<div class="head-g"><div class="wrap"><div class="pre">FAQ</div><h1>Frequently asked questions</h1></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div><section><div class="wrap"><div class="prose"><div class="faq"><details><summary>Does MPM service accounts outside of Illinois?</summary><p>Yes. MPM runs programs nationwide — every state — and ships to domestic and export mills. See <a href="coverage.html">Coverage</a>.</p></details><details><summary>How often do you pick up, and do you operate on weekends?</summary><p>MPM operates 6 days a week and can arrange Sunday pickups on request. Special pickups can be dispatched within 24 hours by our customer service team, and same-day service is available on requests placed before 10:00 am.</p></details><details><summary>Do you supply the containers for my material?</summary><p>Yes. MPM provides a full range of containers, from gaylord boxes and collapsible containers to plastic tubs, bin receptacles and spotted trailers dropped at your facility. See <a href="equipment.html">Equipment</a>.</p></details><details><summary>What types of materials do you take?</summary><p>All grades of paper, aluminum plates and mixed metals, industrial scrap plastics, pallets, and secure-destruction documents.</p></details><details><summary>Does MPM buy old paper inventory?</summary><p>Yes. MPM buys old inventory in both cut sheets and rolls.</p></details><details><summary>How does MPM provide consistent pricing when the market is always changing?</summary><p>Our direct relationships with both domestic and international mills give us the flexibility to take advantage of movement and price.</p></details><details><summary>Will the price I receive fluctuate?</summary><p>Recovered paper is a commodity and pricing varies over time with the amount of material on the market. Your current price on every grade is always visible in your portal login.</p></details><details><summary>Can I see my loads and statements?</summary><p>Every customer gets a login to the MPM portal: pricing by grade, every load with weights and values, monthly statements per site, payment status and recycling impact — updated as loads ship.</p></details></div><p style="margin-top:24px">Still have a question? Call <a href="tel:+17732651200">(773) 265-1200</a> or <a href="contact.html">send us a message</a>.</p></div></div></section>'},
    'contact': {"title": 'Contact | Marcells Paper & Metal', "desc": "Call (773) 265-1200 or tell us how many sites you have and what you're shipping.", "body": '<div class="head-g"><div class="wrap"><div class="pre">Contact</div><h1>Have us look at your loads.</h1></div><div class="tear" aria-hidden="true"><svg viewBox="0 0 1200 28" preserveAspectRatio="none"><path d="M0 14 L38 6 L71 18 L113 4 L152 16 L190 8 L236 20 L271 6 L318 17 L352 3 L399 15 L441 9 L482 21 L530 7 L563 18 L611 5 L648 16 L690 10 L734 22 L779 6 L812 15 L861 3 L903 18 L942 8 L988 19 L1032 6 L1071 16 L1118 4 L1160 17 L1200 9 L1200 28 L0 28 Z"/></svg></div></div><section><div class="wrap">\n  <div class="cgrid">\n    <div><p class="lead">The fastest way is the phone.</p><div class="bigphone"><a href="tel:+17732651200">(773) 265-1200</a></div><p class="muted">Same-day service on requests before 10:00 am. Six days a week, Sunday on request.</p>\n      <div class="box" style="margin-top:28px"><h3>What to tell us</h3><ul><li>How many sites, and where</li><li>What you\'re shipping now — grades, loose or baled</li><li>Roughly how many trucks a month</li><li>Whether you have equipment on site today</li></ul></div>\n      <p style="margin-top:22px" class="muted">4221 W Ferdinand St, Chicago, IL 60624 · Fax (773) 265-1220 · <a href="mailto:info@marcellspaper.com">info@marcellspaper.com</a><br><a href="https://www.google.com/maps/search/?api=1&query=4221+W+Ferdinand+St+Chicago+IL+60624" target="_blank" rel="noopener">Get directions</a></p>\n      <p style="margin-top:14px" class="muted">Already a customer? <a href="https://portals.cietrade.com/MarcellsPaperPortal/login.aspx" target="_blank" rel="noopener"><b>Client Login</b></a></p></div>\n    <div class="form box"><form onsubmit="return sendMail(this)">\n      <label for="name">Name</label><input id="name" name="Name" required placeholder="Your name">\n      <label for="company">Company</label><input id="company" name="Company" placeholder="Company">\n      <label for="reach">Email or phone</label><input id="reach" name="Reach" required placeholder="How should we reach you?">\n      <label for="sites">Number of sites</label><select id="sites" name="Sites"><option>1</option><option>2–5</option><option>6–20</option><option>20+</option></select>\n      <label for="msg">What are you shipping now?</label><textarea id="msg" name="Message" rows="4" placeholder="Grades, loose or baled, trucks per month…"></textarea>\n      <p style="margin-top:18px"><button class="btn" type="submit">Send</button></p>\n      <p style="font-size:13px;color:var(--muted)">Opens a pre-filled email to info@marcellspaper.com from your mail app. Or just call — it\'s faster.</p>\n    </form>\n    <script>\n    function sendMail(f){var b=\'Name: \'+f.Name.value+\'\\nCompany: \'+f.Company.value+\'\\nContact: \'+f.Reach.value+\'\\nSites: \'+f.Sites.value+\'\\n\\n\'+f.Message.value;\n      window.location.href=\'mailto:info@marcellspaper.com?subject=\'+encodeURIComponent(\'Program inquiry - \'+f.Name.value)+\'&body=\'+encodeURIComponent(b);return false;}\n    </script></div>\n  </div>\n</div></section>'},
}
